            visited = set()
            while pq:
                curr_cost, curr_char = heapq.heappop(pq)
                if curr_char == b:
                    return curr_cost
                if curr_char in visited:
                    continue
                visited.add(curr_char)
                for (orig, chg), c in change_cost.items():
